const VERGUETUNG_PRO_EINHEIT_EUR = 28; // Annahme fuer den Business Case, im Ist-Interview verifizieren
const basis = $('Fristen berechnen').first().json;
const vo = basis.vo;
const labels = { formal: 'Formal-Prüfer', diagnose: 'Diagnose-Prüfer', menge: 'Mengen-Prüfer', frist: 'Fristen-Prüfer' };
const icon = { ok: '✅', fehlt: '❌', fehlerhaft: '❌', hinweis: '⚠️' };
const clean = (s) => String(s || '').replace(/\|/g, '/').replace(/\n/g, ' ');
const befunde = [];
for (const item of $input.all()) {
  const r = item.json.output || {};
  for (const b of r.befunde || []) {
    befunde.push({ agent: r.agent, feld: b.feld, status: b.status, fundstelle: b.fundstelle || null, korrekturhinweis: b.korrekturhinweis || null });
  }
}
// --- Code-Urteile (Cloud-Fassung, 27.10.2026): Ist eine Regel im Code entschieden, gilt sie.
// Das Modell bleibt für Fundstelle und Formulierung zuständig; widerspricht es dem Code, gewinnt der Code.
const f = basis.fakten;
const urteile = [];
const urteil = (wert, agent, feld, muster, status, hinweis, fundstelle) => {
  if (wert === null || wert === undefined) return;
  urteile.push({ agent, feld, muster, status: wert ? 'ok' : status, hinweis: wert ? null : hinweis, fundstelle });
};
urteil(f.leitsymptomatik_zulaessig, 'diagnose', 'Leitsymptomatik', /leitsymptom/i, 'fehlerhaft',
  'Für ' + vo.diagnosegruppe + ' sind nur die Leitsymptomatiken a, b oder x (patientenindividuell) zulässig – Verordnung vom Arzt korrigieren lassen.', 'Heilmittelkatalog, Diagnosegruppe ' + vo.diagnosegruppe + ', Leitsymptomatik');
urteil(f.hoechstmenge_eingehalten, 'menge', 'Einheiten je Verordnung', /einheit|menge/i, 'fehlerhaft',
  'Höchstmenge je Verordnung ist ' + f.hoechstmenge_je_vo + ' Einheiten, verordnet sind ' + f.summe_einheiten_vorrangig + ' – Verordnung korrigieren lassen.', 'Heilmittelkatalog, Diagnosegruppe ' + vo.diagnosegruppe + ', Höchstmenge je VO');
urteil(f.ergaenzend_einheiten_ok, 'menge', 'Heilmittel-Kombination (ergänzende Einheiten)', /kombination|ergänz/i, 'fehlerhaft',
  'Das ergänzende Heilmittel hat mehr Einheiten (' + f.summe_einheiten_ergaenzend + ') als die vorrangigen (' + f.summe_einheiten_vorrangig + ') – Verordnung korrigieren lassen.', 'HeilM-RL § 12 Abs. 3');
urteil(f.ergaenzendes_heilmittel_zulaessig, 'menge', 'Heilmittel-Kombination (zulässiges ergänzendes Heilmittel)', /kombination|ergänz/i, 'fehlerhaft',
  'Dieses ergänzende Heilmittel ist für ' + vo.diagnosegruppe + ' nicht vorgesehen – Verordnung korrigieren lassen.', 'Heilmittelkatalog, Diagnosegruppe ' + vo.diagnosegruppe + ', ergänzende Heilmittel');
urteil(f.frequenz_im_rahmen, 'menge', 'Therapiefrequenz', /frequenz/i, 'hinweis',
  'Frequenz liegt außerhalb der Empfehlung von 1–3× pro Woche – zulässig, aber bitte beachten.', 'Heilmittelkatalog (Frequenzempfehlung); HeilM-RL § 12 Abs. 1');
// Formal-Prüfer: Mandat ist nur, ob das Feld ausgefüllt ist (HeilM-RL § 13); den Inhalt prüfen Mengen- bzw. Diagnose-Prüfer.
urteil(f.pflichtangaben?.frequenz, 'formal', 'Therapiefrequenz', /frequenz/i, 'fehlt', 'Therapiefrequenz fehlt – vom Arzt ergänzen lassen.', 'HeilM-RL § 13 Abs. 1');
urteil(f.pflichtangaben?.leitsymptomatik, 'formal', 'Leitsymptomatik', /leitsymptom/i, 'fehlt', 'Leitsymptomatik fehlt – vom Arzt ergänzen lassen.', 'HeilM-RL § 13 Abs. 1');
const kombi = urteile.filter((u) => u.muster.source === 'kombination|ergänz');
for (const u of urteile) {
  const treffer = befunde.filter((b) => b.agent === u.agent && u.muster.test(String(b.feld || '')));
  // Bei zwei Kombinations-Urteilen bestimmt das strengere den Befund
  if (u.status === 'ok' && kombi.length > 1 && kombi.some((k) => k !== u && k.status !== 'ok') && u.muster.source === 'kombination|ergänz') continue;
  if (treffer.length) {
    for (const b of treffer) {
      b.status = u.status; b.korrekturhinweis = u.hinweis; b.fundstelle = b.fundstelle || u.fundstelle; b.quelle = 'code';
    }
  } else if (u.status !== 'ok') {
    befunde.push({ agent: u.agent, feld: u.feld, status: u.status, fundstelle: u.fundstelle, korrekturhinweis: u.hinweis, quelle: 'code' });
  }
}
const kritisch = befunde.filter((b) => b.status === 'fehlt' || b.status === 'fehlerhaft');
const hinweise = befunde.filter((b) => b.status === 'hinweis');
const gesamtstatus = kritisch.length ? 'rot' : hinweise.length ? 'gelb' : 'gruen';
const einheiten = basis.fakten.summe_einheiten || 0;
const risiko = gesamtstatus === 'rot' ? einheiten * VERGUETUNG_PRO_EINHEIT_EUR : 0;
const ampel = {
  rot: '🔴 Bitte nicht behandeln – Verordnung erst korrigieren lassen',
  gelb: '🟡 Behandlung möglich – Hinweise beachten',
  gruen: '🟢 Verordnung in Ordnung'
}[gesamtstatus];
let antwort = '**Verordnungs-Check ' + (vo.verordnung_ref || '') + '**\n\n' + ampel + '\n\n';
if (risiko) antwort += 'Absetzungsrisiko: ca. ' + risiko + ' € (' + einheiten + ' Einheiten × ' + VERGUETUNG_PRO_EINHEIT_EUR + ' €, Annahme)\n\n';
const relevant = kritisch.concat(hinweise);
if (relevant.length) {
  antwort += '| Prüfer | Feld | Status | Was tun? | Fundstelle |\n|---|---|---|---|---|\n';
  for (const b of relevant) {
    antwort += '| ' + (labels[b.agent] || b.agent) + ' | ' + clean(b.feld) + ' | ' + icon[b.status] + ' ' + b.status + ' | ' + clean(b.korrekturhinweis) + ' | ' + clean(b.fundstelle) + ' |\n';
  }
}
antwort += '\n' + befunde.length + ' Prüfpunkte von 4 Prüfern, davon ' + befunde.filter((b) => b.status === 'ok').length + ' in Ordnung.';
return [{ json: {
  verordnung_ref: vo.verordnung_ref || 'ohne Referenz',
  eingabe: { verordnung: vo, fakten: basis.fakten },
  gesamtstatus,
  absetzungsrisiko_eur: risiko,
  zusammenfassung: ampel,
  dauer_ms: Date.now() - basis.start_ms,
  freigabe: 'offen',
  diagnose_auswahl: basis.diagnose_auswahl || { hinweise: [] },
  befunde,
  antwort
} }];

const pruefungId = $input.first().json.id;
const befunde = $('Ergebnis zusammenführen').first().json.befunde || [];
return befunde.map((b) => ({ json: { pruefung_id: pruefungId, agent: b.agent, feld: b.feld, status: b.status, fundstelle: b.fundstelle, korrekturhinweis: b.korrekturhinweis } }));

// Beide Redaktionswege liefern {text, entfernt}. Modus und Felder kommen aus
// "Eingabe prüfen", damit der Extraktor unverändert weiterarbeiten kann.
const eingang = $('Eingabe prüfen').first().json;
const antwort = $input.first().json;
if (typeof antwort.text !== 'string' || antwort.text.trim() === '') {
  throw new Error('Redaktion lieferte keinen Text');
}
return [{ json: {
  ...eingang,
  text: antwort.text,
  redaktion: {
    entfernt: antwort.entfernt ?? [],
    modell: antwort.modell ?? null,
    dauer_ms: antwort.dauer_ms ?? null
  }
} }];

// Text redigieren (Regeln) – JavaScript-Port von redaktion/regeln.py (Valentin Klamka).
// Läuft vollständig in n8n Cloud, kein Text verlässt den Workflow.
// Portiert: alle Regeln, Spannen-Logik, Zusammenfassen gleicher Marker.
// Nicht portiert: das NER-Modell (Davlan BERT) – Namen ohne Rollenwort
// ("Mustermann klagt …") werden in der Cloud NICHT erkannt. Für echte Daten
// ist deshalb der Formularweg vorgesehen (deterministische Redaktion je Feld).
const W = '[\\p{L}\\p{N}_]';
const B = `(?<!${W})`;   // Wortgrenze vorn (Unicode, wie Python \b)
const E = `(?!${W})`;    // Wortgrenze hinten
const R = (src, flags = '') => new RegExp(src.replaceAll('\\b<', B).replaceAll('\\b>', E), 'gu' + flags);
const GR = '[A-ZÄÖÜ]', KL = '[a-zäöüß-]';
const ROLLE = '(?:Patient(?:in|en)?|Versicherte(?:r|n)?|Herr(?:n)?|Frau(?:en)?|Kind(?:er)?|Sohn|Tochter|Ehefrau|Ehemann|Lebenspartner(?:in)?|Mutter|Vater|Angehörige(?:r|n)?)';
const NUMERISCH = R('\\b<(?:\\+49|0049|0)[ \\t\\d/.-]{6,}\\d');
const DATUM = /^\d{1,2}\.\d{1,2}\.\d{4}$/;
const REGELN = [
  ['geburtsdatum', R('\\b<(?:geb(?:oren|\\.)?\\s*(?:am)?|Geb\\.?-?Datum|Geburtsdatum)\\s*:?\\s*\\d{1,2}\\.\\d{1,2}\\.\\d{4}', 'i'), '[Geburtsdatum]'],
  ['versichertennummer', R('\\b<[A-Z]{1,2}\\d{8,10}\\b>'), '[Versichertennummer]'],
  ['email', R('[\\p{L}\\p{N}_.+-]+@[\\p{L}\\p{N}_-]+(?:\\.[\\p{L}\\p{N}_-]+)+'), '[E-Mail]'],
  ['telefon', R('\\b<(?:Tel\\.?|Telefon|Mobil|Handy|Fax)\\s*:?\\s*\\+?[\\d \\t/()-]{6,}\\d', 'i'), '[Telefon]'],
  ['iban-de', R('\\b<DE\\d{2}(?: ?\\d{4}){4} ?\\d{2}\\b>'), '[IBAN]'],
  ['iban', R('\\b<[A-Z]{2}\\d{2}(?: ?[A-Z0-9]{4}){2,7} ?[A-Z0-9]{0,2}\\b>'), '[IBAN]'],
  ['lanr', R('\\b<LANR\\s*:?\\s*\\d{6,10}\\b>', 'i'), 'LANR [LANR]'],
  ['bsnr', R('\\b<BSNR\\s*:?\\s*\\d{6,10}\\b>', 'i'), 'BSNR [BSNR]'],
  ['rolle-name', R(`\\b<${ROLLE}\\s+(?:Dr\\.\\s*)?(?:med\\.\\s*)?(?<name>${GR}${KL}+(?:\\s+${GR}${KL}+)*)`), '[Name]', 'name'],
  ['arzt', R(`\\b<Dr\\.\\s*(?:med\\.\\s*)?(?:dent\\.\\s*)?${GR}${KL}+(?:\\s+${GR}${KL}+)*`), '[Arzt]'],
  ['name-zeile', R('\\b<(?:Nach)?[Nn]ame\\s*:\\s*[^\\n;,]+'), '[Name]'],
  ['anschrift', R('\\b<[A-ZÄÖÜ][a-zäöüß]+(?:straße|strasse|str\\.|weg|allee|platz|ring|gasse|damm|ufer)\\s*\\d+[a-z]?\\b>', 'i'), '[Anschrift]'],
  ['plz-ort', R('\\b<\\d{5}\\s+[A-ZÄÖÜ][a-zäöüß]+(?:\\s+[A-ZÄÖÜ][a-zäöüß]+)?'), '[PLZ Ort]'],
  ['praxis', R(`\\b<Praxis\\s+(?:(?:am|an der|im|für)\\s+)?(?:Dr\\.\\s*(?:med\\.\\s*)?)?${GR}${KL}+(?:\\s+${GR}${KL}+){0,2}`), '[Praxis]'],
];
const NAME_FUER_MARKE = { '[Name]': 'Name', '[Anschrift]': 'Anschrift', '[PLZ Ort]': 'PLZ und Ort', '[Telefon]': 'Telefonnummer', '[E-Mail]': 'E-Mail', '[Versichertennummer]': 'Versichertennummer', '[Geburtsdatum]': 'Geburtsdatum', '[Arzt]': 'Arzt', '[Praxis]': 'Praxis', '[IBAN]': 'IBAN', 'LANR [LANR]': 'LANR', 'BSNR [BSNR]': 'BSNR' };

function regelSpannen(text) {
  const sp = [];
  for (const m of text.matchAll(NUMERISCH)) {
    if (DATUM.test(m[0].trim())) continue;
    sp.push({ start: m.index, end: m.index + m[0].length, marke: '[Telefon]' });
  }
  for (const [, muster, marke, gruppe] of REGELN) {
    for (const m of text.matchAll(new RegExp(muster.source, muster.flags + 'd'))) {
      const [s, e] = gruppe ? m.indices.groups[gruppe] : m.indices[0];
      sp.push({ start: s, end: e, marke });
    }
  }
  return sp;
}
function verschmelze(text, sp) {
  const sortiert = [...sp].sort((a, b) => a.start - b.start || (b.end - b.start) - (a.end - a.start));
  const beh = [];
  for (const s of sortiert) if (!beh.some((b) => b.start < s.end && s.start < b.end)) beh.push(s);
  const zus = [];
  for (const s of beh) {
    const l = zus[zus.length - 1];
    if (l && l.marke === s.marke && /^[ \t,]*$/.test(text.slice(l.end, s.start))) zus[zus.length - 1] = { ...l, end: s.end };
    else zus.push(s);
  }
  return zus;
}
function redigiere(text) {
  if (typeof text !== 'string' || !text.trim()) return { text, entfernt: [] };
  const sp = verschmelze(text, regelSpannen(text));
  const entfernt = [];
  let out = text;
  for (const s of [...sp].sort((a, b) => b.start - a.start)) out = out.slice(0, s.start) + s.marke + out.slice(s.end);
  for (const s of sp) { const n = NAME_FUER_MARKE[s.marke] ?? s.marke.replace(/[[\]]/g, ''); if (!entfernt.includes(n)) entfernt.push(n); }
  return { text: out, entfernt };
}

// --- n8n ---
const r = redigiere($input.first().json.text);
return [{ json: { text: r.text, entfernt: r.entfernt, modell: 'regeln (Cloud, ohne NER)', dauer_ms: null } }];
